type TeamPlayerDraft = { team:string; no:number; name:string; pos:string; role?:"Inti"|"Libero"|"Cadangan"; added?:boolean };

/* NV Analytics update marker: clear temporary match/scouting inputs once per app version,
   while preserving the saved roster, team list, and match identity. */
const NV_APP_VERSION = "1.27.55";
const nvUpdateNotice = (() => {
  try {
    const previousVersion = localStorage.getItem("nv-analytics-app-version");
    if (previousVersion === NV_APP_VERSION) return false;
    const hasExistingData = !!(previousVersion || localStorage.getItem("volleydata-team-rows") || localStorage.getItem("volleydata-players") || localStorage.getItem("nv-analytics-match-name") || sessionStorage.length);
    sessionStorage.clear();
    [
      "volleydata-home-score", "volleydata-away-score", "volleydata-current-set",
      "volleydata-sets-won", "volleydata-completed-sets", "volleydata-match-finished",
      "volleydata-set-opening-server", "volleydata-serving-side", "volleydata-scout-events",
      "volleydata-video-lineups", "volleydata-video-home-team", "volleydata-video-away-team"
    ].forEach(key => localStorage.removeItem(key));
    localStorage.setItem("nv-analytics-app-version", NV_APP_VERSION);
    return hasExistingData;
  } catch { return false; }
})();

