              <div className="score-middle"><span>SET</span><b>{setNumber}</b><small className="set-wins-indicator">{setsWon.Home} – {setsWon.Away} SET</small><small>VS</small><small className="serve-indicator">SERVIS: {servingSide}</small>{matchFinished&&<small className="match-finished-indicator">MATCH SELESAI</small>}</div>
